// /portfolio — generated by `pnpm gen:screen portfolio`, then built from the Portfolio mockup: every client
// the user may see, with its projects/sites and their Project IDs (E1 AC1, AC2). Strings are i18n keys.
import { useEffect, useState } from 'react';
import { Card, FormMessage, PageHeader, useI18n } from '@ocs/ui';
import { loadPortfolio, type ClientSummary, type SiteSummary } from '../api.ts';

type State =
  | { kind: 'loading' }
  | { kind: 'failed' }
  | { kind: 'loaded'; clients: ClientSummary[]; sites: SiteSummary[] };

export function PortfolioPage() {
  const { t } = useI18n();
  const [state, setState] = useState<State>({ kind: 'loading' });

  useEffect(() => {
    loadPortfolio().then(
      (data) => {
        setState({ kind: 'loaded', ...data });
      },
      () => {
        setState({ kind: 'failed' });
      },
    );
  }, []);

  return (
    <>
      <PageHeader eyebrow={`/ ${t('portfolio.title')}`} title={t('portfolio.title')} />
      {state.kind === 'loading' ? <p>{t('common.loading')}</p> : null}
      {state.kind === 'failed' ? <FormMessage tone="error">{t('portfolio.failed')}</FormMessage> : null}
      {state.kind === 'loaded' && state.clients.length === 0 ? (
        <Card>
          <p>{t('portfolio.empty')}</p>
        </Card>
      ) : null}
      {state.kind === 'loaded' ? (
        <div className="ocs-stack">
          {state.clients.map((client) => {
            const sites = state.sites.filter((s) => s.clientId === client.id);
            return (
              <Card
                key={client.id}
                title={`${client.name} · ${client.shortCode} · ${t('portfolio.sites', { count: String(sites.length) })}`}
                titleId={`client-${client.id}`}
              >
                <table className="ocs-table">
                  <thead>
                    <tr>
                      <th scope="col">{t('portfolio.col.projectId')}</th>
                      <th scope="col">{t('portfolio.col.site')}</th>
                      <th scope="col">{t('portfolio.col.city')}</th>
                      <th scope="col">{t('portfolio.col.standard')}</th>
                    </tr>
                  </thead>
                  <tbody>
                    {sites.map((site) => (
                      <tr key={site.id}>
                        <td>{site.projectId}</td>
                        <td>{site.name}</td>
                        <td>{site.cityName}</td>
                        <td>{site.standard}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </Card>
            );
          })}
        </div>
      ) : null}
    </>
  );
}
